import SuccessPopup from '@/components/Popups/SuccessPopup';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import CancelPopup from '@/components/Popups/CancelPopup';
import { MaintenanceOrder } from '@/types/maintenance';

interface Props {
    maintenanceOrder?: MaintenanceOrder | null;
    showSuccessPopup: boolean;
    setShowSuccessPopup: (value: boolean) => void;
    showCancelPopup: boolean;
    setShowCancelPopup: (value: boolean) => void;
    loading: boolean;
    onCloseParent?: () => void;
}
export default function Submission({
    maintenanceOrder,
    setShowCancelPopup,
    setShowSuccessPopup,
    showCancelPopup,
    showSuccessPopup,
    loading,
    onCloseParent,
}: Props) {
    const handleAddAnother = () => {
        setShowSuccessPopup(false);
    };
    return (
        <>
            <div className="flex flex-row md:justify-end justify-center w-full items-center mt-8">
                {maintenanceOrder ? (
                    <SecondaryButton
                        type="button"
                        className="xl:!px-[87px] !px-[40px] xl:py-3 text-[#A21515] border border-red-error-50 xl:font-semibold bg-red-error-50"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        إلغاء المتقدم
                    </SecondaryButton>
                ) : (
                    <SecondaryButton
                        type="button"
                        className="xl:!px-[87px] !px-[40px] xl:py-3 border bg-[#FFE9E9] border-[#E8EFF6] text-[#A21515] xl:font-semibold hover:bg-[#d8bebe] hover:border-[#a13861] hover:text-[#A21515]"
                        onClick={() => setShowCancelPopup(true)}
                    >
                        الغاء
                    </SecondaryButton>
                )}
                <div>
                    {maintenanceOrder ? (
                        <PrimaryButton className="xl:px-[91px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'حفظ التغييرات'}
                        </PrimaryButton>
                    ) : (
                        <PrimaryButton className="xl:px-[125px] xl:py-3 xl:font-semibold ms-6" disabled={loading}>
                            {loading ? 'جاري التحميل...' : 'إضافة'}
                        </PrimaryButton>
                    )}
                </div>
            </div>
            <CancelPopup
                open={showCancelPopup}
                onClickButton1={() => {
                    setShowCancelPopup(false);
                }}
                onClickButton2={() => {
                    setShowCancelPopup(false);
                    onCloseParent?.();
                }}
                text1={maintenanceOrder ? 'تم الغاء تعديل المتقدم' : 'تم الغاء المتقدم'}
                text2={
                    maintenanceOrder
                        ? 'أنت على وشك إلغاء عملية تعديل المتقدم دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                        : 'أنت على وشك إلغاء عملية إضافة المتقدم دون إكمال البيانات المطلوبة. سيتم تجاهل جميع البيانات المدخلة، هل أنت متأكد؟'
                }
                textButton1="إكمال المتقدم"
                textButton2="إلغاء المتقدم"
                onOpenChange={(open) => setShowCancelPopup(open)}
            />
            <SuccessPopup
                text1={maintenanceOrder ? 'تم تعديل المتقدم بنجاح' : 'تم إضافة المتقدم  بنجاح'}
                text2={maintenanceOrder ? 'تم تعديل المتقدم بنجاح.' : 'تم إضافة المتقدم  بنجاح.'}
                textButton1="العودة لقائمة المتقدمين"
                textButton2={maintenanceOrder ? 'العودة لقائمة المتقدمين' : 'إضافة متقدم جديد'}
                open={showSuccessPopup}
                onAddAnother={handleAddAnother}
                onReturnToList={() => {
                    setShowSuccessPopup(false);
                    onCloseParent?.();
                }}
            />
        </>
    );
}
