import Submission from './Submission';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { CustomSelect } from '@/components/dropDown/Dropdown';
import { Textarea } from '@/components/ui/textarea';
import DocumentUpload from '@/components/icons/document/DocumentUpload';
import { useMemo, useState } from 'react';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';
import { Input } from '@/components/ui/input';
import { Applicant } from '../../types/app.types';
import PlusIcon from '@/components/icons/popups/PlusIcon';

type AddAppDialogProps = {
    openAddPopup: boolean;
    setOpenAddPopup: (open: boolean) => void;
    fetchData: () => void;
    data: Applicant[];
};

export default function AddAppDialog({ openAddPopup, setOpenAddPopup, fetchData, data }: AddAppDialogProps) {
    const [showSuccessPopup, setShowSuccessPopup] = useState(false);
    const [showCancelPopup, setShowCancelPopup] = useState(false);
    const [loading, setLoading] = useState(false);
    const [formState, setFormState] = useState<{
        name: string;
        job_id: string;
        level: string;
        work_type: string;
        skills: string;
        cv: File | null;
    }>({
        name: '',
        job_id: '',
        level: '',
        work_type: '',
        skills: '',
        cv: null,
    });

    const jobsOptions = useMemo(() => {
        const uniqueNames = new Map<string, string>();
        data.forEach((item) => {
            const jobName = item.job?.name ?? item.job_title ?? '';
            if (jobName && !uniqueNames.has(jobName)) {
                uniqueNames.set(jobName, jobName);
            }
        });
        return Array.from(uniqueNames.values()).map((name) => ({ label: name, value: name }));
    }, [data]);

    const handleAddApplicant = async () => {
        const payload = new FormData();
        payload.append('name', formState.name);
        const jobVal = formState.job_id.trim();
        if (/^\d+$/.test(jobVal)) {
            payload.append('job_id', jobVal);
        } else if (jobVal) {
            payload.append('job_title', jobVal);
        }
        payload.append('level', formState.level);
        payload.append('work_type', formState.work_type);
        payload.append('skills', formState.skills);
        if (formState.cv) {
            payload.append('cv', formState.cv);
        }

        try {
            await apiPost({
                endpoint: endpoints.applicant.create,
                body: payload as any,
                config: { headers: { 'Content-Type': 'multipart/form-data' } },
            });
            toast.success('تم إضافة المتقدم بنجاح');
            setOpenAddPopup(false);
            setFormState({
                name: '',
                job_id: '',
                level: '',
                work_type: '',
                skills: '',
                cv: null,
            });
            fetchData();
        } catch (error) {
            toast.error('تعذر إضافة المتقدم');
        }
    };

    return (
        <Dialog open={openAddPopup} onOpenChange={setOpenAddPopup}>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="max-w-[700px] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <div className="flex flex-row gap-2 items-center">
                        <PlusIcon />
                        <DialogTitle className="text-xl font-bold text-primery-blue-500">
                            إضافة متقدم للوظيفة
                        </DialogTitle>
                    </div>

                    <div className="w-full border-b border-[#D1D1D1] !mt-4" />
                </DialogHeader>

                <div className="mt-6 space-y-4">
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">اسم المتقدم</label>
                            <Input
                                value={formState.name}
                                onChange={(e) => setFormState((prev) => ({ ...prev, name: e.target.value }))}
                                placeholder="ادخل الاسم"
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">الوظيفة</label>
                            <CustomSelect
                                value={formState.job_id}
                                onValueChange={(value) => setFormState((prev) => ({ ...prev, job_id: value }))}
                                placeholder="اختر الوظيفة"
                                width="w-full"
                                options={jobsOptions}
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">المستوى</label>
                            <CustomSelect
                                value={formState.level}
                                onValueChange={(value) => setFormState((prev) => ({ ...prev, level: value }))}
                                placeholder="المستوى"
                                width="w-full"
                                options={[
                                    { label: 'Junior', value: 'junior' },
                                    { label: 'Mid-level', value: 'mid' },
                                    { label: 'Senior', value: 'senior' },
                                ]}
                            />
                        </div>
                        <div className="space-y-2">
                            <label className="text-primery-blue-900 font-medium text-[15px]">نوع العمل</label>
                            <Input
                                value={formState.work_type}
                                onChange={(e) => setFormState((prev) => ({ ...prev, work_type: e.target.value }))}
                                placeholder="عن بعد / مكتبي / ميداني"
                            />
                        </div>
                    </div>

                    <div className="space-y-2">
                        <label className="text-primery-blue-900 font-medium text-[15px]">المهارات</label>
                        <Textarea
                            value={formState.skills}
                            onChange={(e) => setFormState((prev) => ({ ...prev, skills: e.target.value }))}
                            placeholder="قم بكتابة مهارات المتقدم"
                            className="min-h-[120px]"
                        />
                    </div>

                    <div className="space-y-2">
                        <label className="text-primery-blue-900 font-medium text-[15px]">السيرة الذاتية CV</label>
                        <label className="block border border-dashed border-[#437DB3] rounded-lg p-4 bg-[#F8FAFF] cursor-pointer">
                            <input
                                type="file"
                                accept=".pdf,.doc,.docx"
                                className="hidden"
                                onChange={(e) =>
                                    setFormState((prev) => ({
                                        ...prev,
                                        cv: e.target.files?.[0] ?? null,
                                    }))
                                }
                            />
                            <div className="flex items-center justify-between">
                                <p className="text-xs text-[#625E74]">
                                    {formState.cv ? formState.cv.name : 'قم برفع ملف CV من جهازك هنا'}
                                </p>
                                <DocumentUpload />
                            </div>
                        </label>
                        <p className="text-[10px] text-[#90868C]">الحد الأقصى لحجم الملف 6MB وصيغة PDF</p>
                    </div>

                    <div className="flex flex-row-reverse gap-4 pt-2">
                        <Submission
                            showSuccessPopup={showSuccessPopup}
                            setShowSuccessPopup={setShowSuccessPopup}
                            showCancelPopup={showCancelPopup}
                            setShowCancelPopup={setShowCancelPopup}
                            loading={loading}
                            onCloseParent={() => setOpenAddPopup(false)}
                        />
                    </div>
                </div>
            </DialogContent>
        </Dialog>
    );
}
